def main():
    files = json.loads(zlib.decompress(base64.b64decode(DATA)))
    root = Path(__file__).resolve().parent / 'Bot_Fox_source'
    if root.exists():
        raise SystemExit('Bot_Fox_source already exists. Move this script to another folder.')
    root.mkdir()
    for name, content in files.items():
        path = root / name
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content, encoding='utf-8')
    print('Source files restored:', len(files))
    print('Folder:', root)
    print('Copy your original credential files and databases here before starting the bot.')

if __name__ == '__main__':
    main()
